INSERT INTO notification_templates_en_704 (template_id, version, channel, subject, body, source_id) VALUES
    ('account_login_verification.en-us', 1, 'email', 'Login verification code', 'Use the following code to finish signing in:', 'account_login_verification'),
    ('account_login_verification.en-us', 1, 'sms', '', 'Your login code is:', 'account_login_verification'),
    ('account_recovery_email.en-us', 1, 'email', 'Reset your password', 'You are resetting your account password. Open the link below before it expires to set a new password. If this was not you, ignore this email:', 'account_recovery_email'),
    ('account_registration_verification.en-us', 1, 'email', 'Registration verification code', 'Use the following code to finish registering:', 'account_registration_verification'),
    ('account_registration_verification.en-us', 1, 'sms', '', 'Your registration code is:', 'account_registration_verification'),
    ('acme.http01.epoch_drift.en-us', 1, 'email', 'Nodes held out of DNS during HTTP-01 certificate validation', 'The HTTP-01 certificate validation period for site {{.site_domain}} (started {{.epoch_opened_at}}) froze its participating nodes. {{.node_count}} node(s) added to the line group meanwhile ({{.node_names}}) will not serve DNS for this site until validation ends. They rejoin automatically once validation ends (all challenges withdrawn or expired); no action is needed. If this lasts long, check the certificate issuance task of the site.', 'acme.http01.epoch_drift.zh-cn'),
    ('acme.http01.epoch_drift.en-us', 1, 'sms', '', 'Site {{.site_domain}}: {{.node_count}} new node(s) ({{.node_names}}) stay out of its DNS until certificate validation ends.', 'acme.http01.epoch_drift.zh-cn'),
    ('aggregated_edge.schedule.alert.en-us', 1, 'email', 'Aggregated edge alert: {{.site_domain}}', 'Site {{.site_domain}}, line {{.line}}: {{.alert_text}}. Origin status: {{.origin}}. Open the scheduling page {{.link}} to switch to an access point or keep the current target (when frozen, you can unfreeze and switch, or stay frozen).', 'aggregated_edge.schedule.alert.zh-cn'),
    ('aggregated_edge.schedule.alert.en-us', 1, 'sms', '', 'Aggregated edge alert: site {{.site_domain}} line {{.line}}: {{.alert_text}} (origin: {{.origin}}). Handle it in the console: {{.link}}', 'aggregated_edge.schedule.alert.zh-cn'),
    ('aggregated_edge.tenant.switch.en-us', 1, 'email', 'Line switched automatically for {{.site_domain}}', 'Site {{.site_domain}}: {{.alert_text}}. Before: {{.switch_from}}; after: {{.switch_to}}. View the switch history, switch manually or switch back under Auto switch in the site details: {{.link}}', 'aggregated_edge.tenant.switch.zh-cn'),
    ('aggregated_edge.tenant.switch.en-us', 1, 'sms', '', 'Site {{.site_domain}}: {{.alert_text}} ({{.switch_from}} -> {{.switch_to}}). Details: {{.link}}', 'aggregated_edge.tenant.switch.zh-cn'),
    ('certificate.expired.en-us', 1, 'email', 'Certificate expired: {{.certificate_name}}', 'Certificate {{.certificate_name}} (domains: {{.domains}}) expired on {{.not_after}}. HTTPS access to sites using it is affected. Renew it or upload a new certificate as soon as possible.', 'certificate.expired.zh-cn'),
    ('certificate.expired.en-us', 1, 'sms', '', 'Certificate {{.certificate_name}} expired on {{.not_after}}. HTTPS for sites using it is affected; replace it soon.', 'certificate.expired.zh-cn'),
    ('certificate.expiring.en-us', 1, 'email', 'Certificate expiring soon: {{.certificate_name}}', 'Certificate {{.certificate_name}} (domains: {{.domains}}) expires on {{.not_after}}, in about {{.days_left}} day(s). After that, sites using it cannot serve HTTPS properly. Renew it or upload a new certificate in time.', 'certificate.expiring.zh-cn'),
    ('certificate.expiring.en-us', 1, 'sms', '', 'Certificate {{.certificate_name}} expires on {{.not_after}} (about {{.days_left}} days left). Renew or replace it in time.', 'certificate.expiring.zh-cn'),
    ('certificate.renew_failed.en-us', 1, 'email', 'Certificate auto-renewal failed', 'Auto-renewal of the certificate ({{.domains}}) failed: {{.reason}}. The current certificate expires on {{.not_after}}; the system keeps retrying with backoff. If the cause is validation or CA credentials, fix it first, then request the certificate again on the Certificates page.', 'certificate.renew_failed.zh-cn'),
    ('certificate.renew_failed.en-us', 1, 'sms', '', 'Certificate ({{.domains}}) auto-renewal failed: {{.reason}}. Current one expires {{.not_after}}; retrying.', 'certificate.renew_failed.zh-cn'),
    ('control.db_pool.recovered.en-us', 1, 'email', 'Control database pool {{if eq .cause "instance_restarted"}}alert closed{{else}}recovered{{end}}: {{.instance}}', '{{if eq .cause "instance_restarted"}}The database pool alert for control instance {{.instance}} since {{.since}} (UTC) was closed after the instance restarted ({{.occurred_at}}, UTC). It alerts again if the pool is still saturated after the restart.{{else}}The database pool saturation on control instance {{.instance}} since {{.since}} (UTC) recovered at {{.occurred_at}} (UTC): 3 consecutive samples were normal.{{end}}', 'control.db_pool.recovered.zh-cn'),
    ('control.db_pool.recovered.en-us', 1, 'sms', '', 'Control {{.instance}} database pool {{if eq .cause "instance_restarted"}}alert closed after restart{{else}}is back to normal{{end}}.', 'control.db_pool.recovered.zh-cn'),
    ('control.db_pool.saturated.en-us', 1, 'email', 'Control database pool saturated: {{.instance}}', 'The database pool of control instance {{.instance}} was found saturated at {{.occurred_at}} (UTC); requests are queuing for connections. In use: {{.in_use}}/{{.max_conns}}, of which {{.resident_conns}} are resident (LISTEN, session locks) and {{.request_capacity}} are left for requests. This period: {{.queued}} queued acquisitions, average wait {{.avg_wait_ms}} ms, reasons: {{.reasons}} (saturated = all connections in use, slow_acquire = average wait over 100 ms, canceled_acquire = a request gave up waiting). Rule: sampled every 10 seconds; alerts after 3 consecutive saturated samples or average waits over 100 ms, or when a request gives up while saturated or queued; recovers after 3 normal samples; repeats within 15 minutes are notified once. Check the pool trend of the last hour on the System maintenance page and look for long transactions, slow queries or transactions holding a second connection.', 'control.db_pool.saturated.zh-cn'),
    ('control.db_pool.saturated.en-us', 1, 'sms', '', 'Control {{.instance}} database pool is saturated; requests are queuing (in use {{.in_use}}/{{.max_conns}}). Please act soon.', 'control.db_pool.saturated.zh-cn'),
    ('domain.claim.completed.en-us', 1, 'email', 'Domain claim completed', 'The claim of domain {{.domain}} is complete. {{.site_count}} conflicting site(s) of other accounts were disabled automatically. You can now add this domain.', 'domain.claim.completed.zh-cn'),
    ('domain.claim.completed.en-us', 1, 'sms', '', 'Domain {{.domain}} claim completed; {{.site_count}} conflicting site(s) disabled.', 'domain.claim.completed.zh-cn'),
    ('domain.claim.suspended.en-us', 1, 'email', 'Site domain claimed by another account', 'Your site domain {{.domain}} was claimed by an account that verified its ownership, and sites using it were disabled automatically. Remove the domain to re-enable the site. To dispute, contact the platform administrator.', 'domain.claim.suspended.zh-cn'),
    ('domain.claim.suspended.en-us', 1, 'sms', '', 'Your site domain {{.domain}} was claimed by a verified owner; related sites are disabled. Contact the administrator to dispute.', 'domain.claim.suspended.zh-cn'),
    ('domain.ownership.expired.en-us', 1, 'email', 'Domain ownership verification expired', 'Ownership re-verification of domain {{.apex}} failed three times in a row, so the verification has expired. Sites are not affected. Check the TXT record and verify again so that no other account can verify this domain.', 'domain.ownership.expired.zh-cn'),
    ('domain.ownership.expired.en-us', 1, 'sms', '', 'Ownership re-verification of {{.apex}} kept failing and has expired. Please verify again.', 'domain.ownership.expired.zh-cn'),
    ('identity.migrated_account.en-us', 1, 'email', 'Your account has moved to the new platform', 'Your account on {{.source_name}} has moved to the new platform with username {{.username}}. Open {{.link}} and use "Forgot password" to set a new password, then sign in.', 'identity.migrated_account.zh-cn'),
    ('identity.migrated_account.en-us', 1, 'sms', '', 'Your {{.source_name}} account {{.username}} moved to the new platform. Open {{.link}} to set a new password.', 'identity.migrated_account.zh-cn'),
    ('identity_secondary_verification.en-us', 1, 'email', 'Secondary identity verification required', '<p>Hello {{.username}}. The platform requires you to complete a secondary identity verification with the ID card used for your first verification by {{.deadline}}. If it is not completed in time, your sites may be locked.</p>', 'identity_secondary_verification'),
    ('identity_secondary_verification.en-us', 1, 'sms', '', 'The platform requires a secondary identity verification with your original ID card by {{.deadline}}.', 'identity_secondary_verification'),
    ('installation_ban.rejected.en-us', 1, 'email', 'Node rejected license state: {{.node_name}}', 'Node {{.node_name}} ({{.node_ip}}) refused to apply the license state sent by the control plane at {{.occurred_at}} (UTC) (revision {{.revision}}, reason {{.reason}}). The refusal is permanent: the same revision is not sent again and the node keeps its previous license state until the licensor issues a new revision. Check the License credential column of the node on the Nodes page, and the node version and installation ban errors in journalctl -u cdnca-edge-agent. Once the node is upgraded or fixed, the next revision arrives automatically. Each node and revision is notified once.', 'installation_ban.rejected.zh-cn'),
    ('installation_ban.rejected.en-us', 1, 'sms', '', 'Node {{.node_name}} rejected license revision {{.revision}}; it will not be resent. Please act soon.', 'installation_ban.rejected.zh-cn'),
    ('market.commission.exhausted.en-us', 1, 'email', 'Node market: {{.currency}} commission prepayment used up', 'Your {{.currency}} commission prepayment is used up (now {{.observed}}, minor currency unit). Scheduling of the direct-settlement subscriptions you sold is paused (credentials are not revoked) and resumes automatically after a top-up.', 'market.commission.exhausted.zh-cn'),
    ('market.commission.exhausted.en-us', 1, 'sms', '', 'Node market: {{.currency}} commission prepayment used up; your direct-settlement offers are paused. Please top up.', 'market.commission.exhausted.zh-cn'),
    ('market.commission.low.en-us', 1, 'email', 'Node market: {{.currency}} commission prepayment below alert line', 'Your {{.currency}} commission prepayment {{.observed}} is below your alert line {{.cap}} (minor currency unit, e.g. cents). When it runs out, your direct-settlement offers stop being scheduled. Please top up in time.', 'market.commission.low.zh-cn'),
    ('market.commission.low.en-us', 1, 'sms', '', 'Node market: {{.currency}} commission prepayment {{.observed}} is below alert line {{.cap}} (minor unit).', 'market.commission.low.zh-cn'),
    ('market.commission.restored.en-us', 1, 'email', 'Node market: {{.currency}} commission prepayment restored', 'Your {{.currency}} commission prepayment is back to {{.observed}} (minor currency unit). Direct-settlement subscriptions paused for lack of balance are scheduled again.', 'market.commission.restored.zh-cn'),
    ('market.commission.restored.en-us', 1, 'sms', '', 'Node market: {{.currency}} commission prepayment topped up; direct-settlement offers resumed.', 'market.commission.restored.zh-cn'),
    ('market.complaint.actioned.en-us', 1, 'email', 'Node market: platform action on subscription ({{.outcome}})', 'Following stop ticket {{.complaint}} (category {{.category}}), the platform took action on subscription {{.subscription}} (your ID {{.target}}): {{.outcome}} (warn = warning, pause = scheduling paused on the supplier''s nodes, stop = service stopped, blacklist_domain = domain {{.domain}} blacklisted, released = lifted). To object, contact the platform; billing issues go through the dispute process.', 'market.complaint.actioned.zh-cn'),
    ('market.complaint.actioned.en-us', 1, 'sms', '', 'Node market subscription {{.subscription}} actioned by the platform: {{.outcome}} (ticket {{.complaint}}).', 'market.complaint.actioned.zh-cn'),
    ('market.complaint.resolved.en-us', 1, 'email', 'Node market: stop ticket handled ({{.outcome}})', 'Your stop ticket {{.complaint}} (category {{.category}}) against downstream ID {{.target}} was handled by the platform: {{.outcome}} (rejected = rejected, warn = warning, pause = that downstream paused on your nodes, stop = service stopped, blacklist_domain = domain {{.domain}} blacklisted, released = lifted). The platform does not disclose the downstream''s real identity; billing issues go through the dispute process.', 'market.complaint.resolved.zh-cn'),
    ('market.complaint.resolved.en-us', 1, 'sms', '', 'Node market stop ticket {{.complaint}} (downstream {{.target}}) handled: {{.outcome}}.', 'market.complaint.resolved.zh-cn'),
    ('market.direct_topup.paid.en-us', 1, 'email', 'Node market: top-up at {{.peer}} received', 'Your top-up of {{.observed}} ({{.currency}}, minor currency unit, e.g. cents) at supplier {{.peer}} has arrived and was added to your balance with that supplier. Top-up order {{.topup}}. The money went directly to the supplier; the platform does not handle funds.', 'market.direct_topup.paid.zh-cn'),
    ('market.direct_topup.paid.en-us', 1, 'sms', '', 'Node market: your top-up of {{.observed}} {{.currency}} (minor unit) at {{.peer}} arrived. Order {{.topup}}.', 'market.direct_topup.paid.zh-cn'),
    ('market.direct_topup.received.en-us', 1, 'email', 'Node market: top-up received from {{.peer}}', 'Subscriber {{.peer}} topped up {{.observed}} ({{.currency}}, minor currency unit) through your payment channel. The market added it to their balance with you. Top-up order {{.topup}}.', 'market.direct_topup.received.zh-cn'),
    ('market.direct_topup.received.en-us', 1, 'sms', '', 'Node market: subscriber {{.peer}} topped up {{.observed}} {{.currency}} (minor unit). Order {{.topup}}.', 'market.direct_topup.received.zh-cn'),
    ('market.downstream.attacked.en-us', 1, 'email', 'Node market: downstream site under attack', 'On an offer you resell, a downstream site was attacked during window {{.window_start}} (Unix seconds, 5 minutes) and was handled by the leaf node. A buyer subscribed directly to you appears as your subscription {{.subscription}}; further downstream only as downstream ID {{.downstream}} (as in the subscriber view; - when not applicable). Site identity and attack details go only to the site owner. Each downstream is notified at most once per hour.', 'market.downstream.attacked.zh-cn'),
    ('market.downstream.attacked.en-us', 1, 'sms', '', 'Node market: downstream site attacked (subscription {{.subscription}}, downstream {{.downstream}}, window {{.window_start}}).', 'market.downstream.attacked.zh-cn'),
    ('market.feedback.opened.en-us', 1, 'email', 'Node market: fault report on {{.offer}}', 'A subscriber filed a fault report on offer {{.offer}} (subscription {{.subscription}}), number {{.feedback}}, category {{.category}} (outage, degraded = quality drop, config = configuration, billing, other). Reply or mark it in progress within 72 hours; otherwise the subscriber can escalate it to a dispute. View and reply under Node market > Supply > Fault reports.', 'market.feedback.opened.zh-cn'),
    ('market.feedback.opened.en-us', 1, 'sms', '', 'Node market offer {{.offer}} got a fault report ({{.category}}). Please handle it within 72 hours.', 'market.feedback.opened.zh-cn'),
    ('market.feedback.updated.en-us', 1, 'email', 'Node market: fault report on {{.offer}} updated', 'Fault report {{.feedback}} on offer {{.offer}} (subscription {{.subscription}}) was updated: {{.action}} (reply = new reply, in_progress = seller working on it, resolved = seller marked resolved, closed, reopened = subscriber reopened, escalated = subscriber escalated to a dispute; operator_ prefix = platform intervention). View the conversation in the node market.', 'market.feedback.updated.zh-cn'),
    ('market.feedback.updated.en-us', 1, 'sms', '', 'Node market offer {{.offer}} fault report updated ({{.action}}).', 'market.feedback.updated.zh-cn'),
    ('market.limit.reached.en-us', 1, 'email', 'Node market: {{.offer}} {{.metric}} limit reached', '{{.metric}} of offer {{.offer}} (subscription {{.subscription}}) reached {{.observed}}, limit {{.cap}}. Action taken: {{.action}} (pause = scheduling paused, stop = service stopped). It resumes automatically after usage drops or the subscription renews.', 'market.limit.reached.zh-cn'),
    ('market.limit.reached.en-us', 1, 'sms', '', 'Node market offer {{.offer}} {{.metric}} reached limit {{.cap}}; action: {{.action}}.', 'market.limit.reached.zh-cn'),
    ('market.limit.recovered.en-us', 1, 'email', 'Node market: {{.offer}} {{.metric}} recovered', '{{.metric}} of offer {{.offer}} (subscription {{.subscription}}) is back under the limit. The {{.action}} action was lifted and scheduling resumed automatically.', 'market.limit.recovered.zh-cn'),
    ('market.limit.recovered.en-us', 1, 'sms', '', 'Node market offer {{.offer}} {{.metric}} limit recovered.', 'market.limit.recovered.zh-cn'),
    ('market.limit.warn80.en-us', 1, 'email', 'Node market: {{.offer}} {{.metric}} at 80% of limit', '{{.metric}} of offer {{.offer}} (subscription {{.subscription}}) is {{.observed}}, limit {{.cap}}: 80% reached. Each stage is notified once per period.', 'market.limit.warn80.zh-cn'),
    ('market.limit.warn80.en-us', 1, 'sms', '', 'Node market offer {{.offer}} {{.metric}} at 80% of limit: {{.observed}}/{{.cap}}.', 'market.limit.warn80.zh-cn'),
    ('market.limit.warn95.en-us', 1, 'email', 'Node market: {{.offer}} {{.metric}} at 95% of limit', '{{.metric}} of offer {{.offer}} (subscription {{.subscription}}) is {{.observed}}, limit {{.cap}}: 95% reached. At the limit, the action set by the seller applies.', 'market.limit.warn95.zh-cn'),
    ('market.limit.warn95.en-us', 1, 'sms', '', 'Node market offer {{.offer}} {{.metric}} at 95% of limit: {{.observed}}/{{.cap}}.', 'market.limit.warn95.zh-cn'),
    ('market.node.action.en-us', 1, 'email', 'Node market: whole-node action on a node of offer {{.offer}}', 'A node of your subscribed offer {{.offer}} (region {{.region}}, carrier {{.carrier}}) had a whole-node action at {{.at}} ({{.source}}/{{.event}}, e.g. kernel ban or XDP switch); all sites on that node may be affected. The same action on the same node is notified at most once per hour. Attacked sites and client details are not disclosed.', 'market.node.action.zh-cn'),
    ('market.node.action.en-us', 1, 'sms', '', 'Node market offer {{.offer}}: node ({{.region}}/{{.carrier}}) had a whole-node action at {{.at}}: {{.source}}/{{.event}}.', 'market.node.action.zh-cn'),
    ('market.node.overloaded.en-us', 1, 'email', 'Node market: node {{.node}} overloaded and removed', 'CPU or memory of node {{.node}} (pool {{.pool}}) stayed above threshold {{.threshold}} (CPU/memory %). It was removed from the DNS of offers using this threshold and returns automatically once load drops.', 'market.node.overloaded.zh-cn'),
    ('market.node.overloaded.en-us', 1, 'sms', '', 'Node market node {{.node}} (pool {{.pool}}) exceeded threshold {{.threshold}} and was removed from offers.', 'market.node.overloaded.zh-cn'),
    ('market.node.probe_recovered.en-us', 1, 'email', 'Subscribed node reachable again from this control plane: {{.node}}', 'Probes from this control plane to subscribed node {{.node}} (seller {{.seller}}, subscription {{.supply}}) recovered at {{.occurred_at}} (UTC). Market verdict: {{.market_health}}.', 'market.node.probe_recovered.zh-cn'),
    ('market.node.probe_recovered.en-us', 1, 'sms', '', 'Subscribed node {{.node}} (seller {{.seller}}) is reachable again from this control plane.', 'market.node.probe_recovered.zh-cn'),
    ('market.node.probe_unreachable.en-us', 1, 'email', 'Subscribed node unreachable from this control plane: {{.node}}', 'Probes from this control plane found subscribed node {{.node}} (seller {{.seller}}, subscription {{.supply}}) unreachable repeatedly at {{.occurred_at}} (UTC); probes from all its line groups failed. Market verdict: {{.market_health}}. Whether DNS stops is decided by the market verdict: while the market still considers the node healthy it keeps serving DNS, and only the network between this control plane and the node may be faulty. Check Nodes > Line groups, or contact the seller.', 'market.node.probe_unreachable.zh-cn'),
    ('market.node.probe_unreachable.en-us', 1, 'sms', '', 'Subscribed node {{.node}} (seller {{.seller}}) keeps failing probes from this control plane; market verdict {{.market_health}} decides DNS. See Line groups.', 'market.node.probe_unreachable.zh-cn'),
    ('market.node.recovered.en-us', 1, 'email', 'Node market: node {{.node}} recovered', 'Load of node {{.node}} (pool {{.pool}}) stayed below threshold {{.threshold}} (CPU/memory %). It is back in the DNS of the related offers.', 'market.node.recovered.zh-cn'),
    ('market.node.recovered.en-us', 1, 'sms', '', 'Node market node {{.node}} (pool {{.pool}}) load dropped; scheduling resumed.', 'market.node.recovered.zh-cn'),
    ('market.overdraft.capped.en-us', 1, 'email', 'Node market: {{.offer}} overdraft cap reached', 'The overdraft {{.observed}} of offer {{.offer}} (subscription {{.subscription}}) reached the cap {{.cap}} (minor currency unit). Action taken: {{.action}}. It resumes automatically after a top-up offsets it.', 'market.overdraft.capped.zh-cn'),
    ('market.overdraft.capped.en-us', 1, 'sms', '', 'Node market offer {{.offer}} overdraft reached cap {{.cap}}; action: {{.action}}.', 'market.overdraft.capped.zh-cn'),
    ('market.overdraft.warn.en-us', 1, 'email', 'Node market: {{.offer}} overdraft near cap', 'Offer {{.offer}} (subscription {{.subscription}}) is overdrawn by {{.observed}}, cap {{.cap}} ({{.currency}}, minor currency unit). Scheduling pauses at the cap; top-ups offset the overdraft first.', 'market.overdraft.warn.zh-cn'),
    ('market.overdraft.warn.en-us', 1, 'sms', '', 'Node market offer {{.offer}} overdraft {{.observed}} {{.currency}} is near cap {{.cap}}.', 'market.overdraft.warn.zh-cn'),
    ('market.plugin.promo_charge.en-us', 1, 'email', 'Plugin market: free plugin {{.plugins}} becomes monthly paid soon', 'The free-for-now plugin {{.plugins}} you claimed becomes a monthly paid plugin at {{.at}}: {{.observed}} per month ({{.currency}} cents), first charged from your prepaid balance. If the balance is short, the monthly plugin arrears rules apply: it keeps working during the grace period and is disabled if still unpaid afterwards. To stop, cancel renewal under Plugin market > My plugins.', 'market.plugin.promo_charge.zh-cn'),
    ('market.plugin.promo_charge.en-us', 1, 'sms', '', 'Free plugin {{.plugins}} becomes monthly paid at {{.at}}. Keep enough balance.', 'market.plugin.promo_charge.zh-cn'),
    ('market.plugin.restored.en-us', 1, 'email', 'Node market: {{.offer}} plugins restored', 'Offer {{.offer}} (subscription {{.subscription}}) provides {{.plugins}} again.', 'market.plugin.restored.zh-cn'),
    ('market.plugin.restored.en-us', 1, 'sms', '', 'Node market offer {{.offer}} provides {{.plugins}} again.', 'market.plugin.restored.zh-cn'),
    ('market.plugin.unavailable.en-us', 1, 'email', 'Node market: {{.offer}} plugins no longer provided', 'The upstream of offer {{.offer}} (subscription {{.subscription}}) no longer provides {{.plugins}}. These features fell back to basic protection on this offer; sites keep serving.', 'market.plugin.unavailable.zh-cn'),
    ('market.plugin.unavailable.en-us', 1, 'sms', '', 'Node market offer {{.offer}} no longer provides {{.plugins}}; basic protection applies.', 'market.plugin.unavailable.zh-cn'),
    ('market.prepaid.exhausted.en-us', 1, 'email', 'Node market: {{.offer}} prepayment used up', 'The prepaid balance of offer {{.offer}} (subscription {{.subscription}}) cannot cover this period. Action taken: {{.action}} (pause = scheduling paused, stop = service stopped). The subscription stays open and resumes automatically after a top-up.', 'market.prepaid.exhausted.zh-cn'),
    ('market.prepaid.exhausted.en-us', 1, 'sms', '', 'Node market offer {{.offer}} prepayment used up; action: {{.action}}.', 'market.prepaid.exhausted.zh-cn'),
    ('market.prepaid.low.en-us', 1, 'email', 'Node market: {{.currency}} prepaid balance below alert line', 'Your {{.currency}} prepaid balance {{.observed}} is below your alert line {{.cap}} (minor currency unit, e.g. cents). When it runs out, offers stop being scheduled. Please top up in time.', 'market.prepaid.low.zh-cn'),
    ('market.prepaid.low.en-us', 1, 'sms', '', 'Node market {{.currency}} prepaid balance {{.observed}} is below alert line {{.cap}} (minor unit).', 'market.prepaid.low.zh-cn'),
    ('market.prepaid.restored.en-us', 1, 'email', 'Node market: {{.offer}} restored', 'Payment for offer {{.offer}} (subscription {{.subscription}}) was received. The {{.action}} action was lifted and scheduling resumed automatically.', 'market.prepaid.restored.zh-cn'),
    ('market.prepaid.restored.en-us', 1, 'sms', '', 'Node market offer {{.offer}} topped up; scheduling resumed.', 'market.prepaid.restored.zh-cn'),
    ('market.renewal.compensated.en-us', 1, 'email', 'Node market: {{.offer}} compensated for upstream pause', 'All supply of offer {{.offer}} (subscription {{.subscription}}) was paused for upstream reasons (upstream arrears, overdraft cap, or unpaid platform commission, not the subscriber''s fault), and renewal stopped meanwhile. Under compensation rule upstream-pause/v1, paid time without service during the pause is compensated once: {{.action}} (extended = expiry extended by {{.observed}} seconds to {{.at}}, no cash refund; refunded = subscription ended, {{.observed}} ({{.currency}} minor unit) refunded per second to the subscriber''s balance with this seller). Fees for the pause are not charged after it resumes; each pause is compensated once. If some supply was still available, it is not a pause and no compensation applies.', 'market.renewal.compensated.zh-cn'),
    ('market.renewal.compensated.en-us', 1, 'sms', '', 'Node market offer {{.offer}} compensated for upstream pause ({{.action}}).', 'market.renewal.compensated.zh-cn'),
    ('market.renewal.resumed.en-us', 2, 'email', 'Node market: {{.offer}} renewal resumed', 'The reason renewal of offer {{.offer}} (subscription {{.subscription}}) stopped ({{.action}}) has been cleared. The next renewal counts from now; nothing is charged for the stopped period. If the reason was upstream_paused, paid time without service was added to the expiry; see the compensation notice.', 'market.renewal.resumed.zh-cn'),
    ('market.renewal.resumed.en-us', 2, 'sms', '', 'Node market offer {{.offer}} renewal resumed.', 'market.renewal.resumed.zh-cn'),
    ('market.renewal.stopped.en-us', 2, 'email', 'Node market: {{.offer}} renewal stopped', 'Renewal of offer {{.offer}} (subscription {{.subscription}}) stopped. Reason: {{.action}} (seller_frozen = seller frozen by the platform, buyer_frozen = subscriber frozen by the platform, upstream_lost = upstream supply lost, no_grant = no valid grant, upstream_paused = all supply paused for upstream arrears or unpaid platform commission). From now on future periods are not renewed and daily fees are not charged; usage already incurred is settled as usual. Renewal resumes automatically once the reason clears, with nothing charged for the stopped period. upstream_paused: on resume, paid time without service is added to the expiry, no cash refund; if the subscription ends during the pause, it is refunded per second; each pause is compensated once.', 'market.renewal.stopped.zh-cn'),
    ('market.renewal.stopped.en-us', 2, 'sms', '', 'Node market offer {{.offer}} renewal stopped (reason {{.action}}); daily fees no longer charged.', 'market.renewal.stopped.zh-cn'),
    ('market.seller.default_compensated.en-us', 1, 'email', 'Node market: compensation for {{.peer}} default received', 'Supplier {{.peer}} was ruled in default. The platform paid you {{.observed}} ({{.currency}}, minor currency unit) pro rata from its deposit into your platform prepaid balance (not refunded to the original payment method). Your former balance with this supplier was {{.cap}}; the uncompensated part remains your claim against the supplier.', 'market.seller.default_compensated.zh-cn'),
    ('market.seller.default_compensated.en-us', 1, 'sms', '', 'Node market: supplier {{.peer}} in default; {{.observed}} {{.currency}} paid to your platform balance from its deposit (your balance there: {{.cap}}).', 'market.seller.default_compensated.zh-cn'),
    ('market.seller.defaulted.en-us', 1, 'email', 'Node market: you have been ruled in default', 'Your control plane has been offline, or your offers have had no online nodes, for a long time, so you were ruled in default. The platform paid subscribers {{.observed}} ({{.currency}}, minor currency unit) from your deposit. Your supply permission is suspended and your offers are delisted; the remaining deposit is frozen until the dispute period ends and operations decide. To object, contact platform operations.', 'market.seller.defaulted.zh-cn'),
    ('market.seller.defaulted.en-us', 1, 'sms', '', 'Node market: you were ruled in default; {{.observed}} {{.currency}} of your deposit paid subscribers. Supply suspended.', 'market.seller.defaulted.zh-cn'),
    ('market.seller.deposit_mode.en-us', 1, 'email', 'Node market: deposit setting changed', 'Platform operations changed your anti-default deposit setting to {{.action}} (inherit = follow the global switch, on = enabled for you, off = disabled for you). When enabled and the deposit is short, new subscriptions and top-ups are paused. See the amount due and pay it on the Deposit page of the developer platform.', 'market.seller.deposit_mode.zh-cn'),
    ('market.seller.deposit_mode.en-us', 1, 'sms', '', 'Node market: your deposit setting was changed to {{.action}} (inherit/on/off).', 'market.seller.deposit_mode.zh-cn'),
    ('market.seller.deposit_shortfall.en-us', 1, 'email', 'Node market: deposit short, please top up', 'Your anti-default deposit is {{.observed}} ({{.currency}}, minor currency unit, e.g. cents), below the required {{.cap}}. Until it is topped up, your offers accept no new subscriptions and subscribers cannot top up with you online; existing subscriptions are not affected. Top up on the Deposit page of the developer platform.', 'market.seller.deposit_shortfall.zh-cn'),
    ('market.seller.deposit_shortfall.en-us', 1, 'sms', '', 'Node market: deposit {{.observed}} {{.currency}} is below required {{.cap}} (minor unit); new subscriptions paused. Please top up.', 'market.seller.deposit_shortfall.zh-cn'),
    ('market.site.paused.en-us', 1, 'email', 'Node market: site {{.site}} paused on offer', 'Leaf site {{.site}} of offer {{.offer}} (subscription {{.subscription}}, downstream ID {{.downstream}}) triggered {{.count}} whole-node actions on pool {{.pool}} within 24 hours, over the platform limit, so its scheduling on this offer was paused. Sites with a backup offer switch to it. Once the 24-hour count drops, a supplier with auto pause enabled can resume it.', 'market.site.paused.zh-cn'),
    ('market.site.paused.en-us', 1, 'sms', '', 'Node market offer {{.offer}} (sub {{.subscription}}, downstream {{.downstream}}): site {{.site}} paused on pool {{.pool}} after {{.count}} node actions in 24h.', 'market.site.paused.zh-cn'),
    ('market.site.resumed.en-us', 1, 'email', 'Node market: site {{.site}} scheduled again', 'The auto pause of leaf site {{.site}} of offer {{.offer}} (subscription {{.subscription}}, downstream ID {{.downstream}}) on pool {{.pool}} ({{.count}} times within 24 hours when paused) was lifted. Scheduling resumed and the whole-node action count restarts now.', 'market.site.resumed.zh-cn'),
    ('market.site.resumed.en-us', 1, 'sms', '', 'Node market offer {{.offer}} (sub {{.subscription}}, downstream {{.downstream}}): site {{.site}} resumed on pool {{.pool}} (paused at {{.count}}).', 'market.site.resumed.zh-cn'),
    ('market.supply.all_overloaded.en-us', 1, 'email', 'Node market: all nodes in pool {{.pool}} overloaded', 'All nodes in pool {{.pool}} are overloaded at threshold {{.threshold}} (CPU/memory %), so offers using it have no DNS records for now (no fallback kept). Sites with a backup offer switch to it; this recovers automatically once nodes cool down.', 'market.supply.all_overloaded.zh-cn'),
    ('market.supply.all_overloaded.en-us', 1, 'sms', '', 'Node market pool {{.pool}}: all nodes overloaded (threshold {{.threshold}}); related offers have no DNS now.', 'market.supply.all_overloaded.zh-cn'),
    ('market.supply.cancel_available.en-us', 1, 'email', 'Node market: {{.offer}} can be cancelled free of charge', 'Offer {{.offer}} (subscription {{.subscription}}) has had no online nodes for over 30 minutes. You can cancel it free of charge in My subscriptions: effective immediately, and the remaining paid time is refunded to your balance with that supplier (not to the original payment method). The option disappears once nodes are back online.', 'market.supply.cancel_available.zh-cn'),
    ('market.supply.cancel_available.en-us', 1, 'sms', '', 'Node market offer {{.offer}} still has no online nodes; you can now cancel free of charge.', 'market.supply.cancel_available.zh-cn'),
    ('market.supply.node_delivery_failed.en-us', 1, 'email', 'Market subscription config not effective on nodes', 'Revision {{.revision}} of the config of site {{.domain}} sent to market supply {{.supply}} was applied by the supplier but did not take effect on its nodes (partial failure). Reason: {{.reason}}. Check the delivery result of this site on the node market page, fix the cause and send it again, or contact the supplier.', 'market.supply.node_delivery_failed.zh-cn'),
    ('market.supply.node_delivery_failed.en-us', 1, 'sms', '', 'Site {{.domain}} config revision {{.revision}} on market supply {{.supply}} failed on supplier nodes: {{.reason}}.', 'market.supply.node_delivery_failed.zh-cn'),
    ('market.supply.outage.en-us', 1, 'email', 'Node market: {{.offer}} has no online nodes', 'Offer {{.offer}} (subscription {{.subscription}}) has no online nodes right now. Nothing is billed meanwhile: daily plans are credited to your balance with that supplier for the offline time, and pay-as-you-go has no traffic to charge. Sites with a backup offer or own nodes switch automatically; otherwise subscribe to another offer. After 30 minutes you can cancel free of charge in My subscriptions.', 'market.supply.outage.zh-cn'),
    ('market.supply.outage.en-us', 1, 'sms', '', 'Node market offer {{.offer}} has no online nodes; not billed meanwhile, sites switch to backup.', 'market.supply.outage.zh-cn'),
    ('market.supply.receipt_unconfirmed.en-us', 1, 'email', 'Market subscription config not confirmed', 'Revision {{.revision}} of the config of site {{.domain}} sent to market supply {{.supply}} got a leaf response, but reconciliation still could not confirm the result and it was marked inconsistent. Reason: {{.reason}}. Send it again for this site on the node market page, or check with the supplier.', 'market.supply.receipt_unconfirmed.zh-cn'),
    ('market.supply.receipt_unconfirmed.en-us', 1, 'sms', '', 'Site {{.domain}} config revision {{.revision}} on market supply {{.supply}} is unconfirmed: {{.reason}}.', 'market.supply.receipt_unconfirmed.zh-cn'),
    ('market.supply.restored.en-us', 1, 'email', 'Node market: {{.offer}} restored', 'Offer {{.offer}} (subscription {{.subscription}}) has online nodes again. Fees for the offline time were credited to your balance; sites switch back per the failback policy.', 'market.supply.restored.zh-cn'),
    ('market.supply.restored.en-us', 1, 'sms', '', 'Node market offer {{.offer}} has online nodes again.', 'market.supply.restored.zh-cn'),
    ('market.terms.changed.en-us', 3, 'email', 'Node market: {{.offer}} {{if eq .category "offer_delisted"}}delisted, no renewal after expiry{{else}}terms changed{{end}}', '{{if eq .category "offer_delisted"}}The seller delisted offer {{.offer}} (subscription {{.subscription}}): new purchases have stopped. Your subscription is served under the paid terms until {{.at}}, then it is not renewed, closes automatically and is no longer charged. To keep going, choose another offer and move your sites before it expires.{{else}}The seller changed the terms of offer {{.offer}} (subscription {{.subscription}}). Change: {{.category}} (price_up/price_down = price raised/lowered, limits_stricter/limits_looser = limits tightened/loosened, sla_added/sla_removed = SLA added/removed, sla_better/sla_worse = SLA improved/worsened, *_mixed = mixed or not comparable, resale_on/resale_off = resale allowed/no longer allowed after renewal, site_pause_on/site_pause_off = same-site auto pause on/off after renewal). Stricter limits and a worse or removed SLA count as a price rise; with price and limits unchanged, an unchanged or better SLA renews under the new terms; the resale and site pause switches do not affect renewal conditions but apply after renewal. Based on your renewal price condition, at the end of this period it will {{.action}} (renew = renew under the new terms, close = not renew and close). To adjust, change the renewal condition or cancel the subscription before it expires.{{end}}', 'market.terms.changed.zh-cn'),
    ('market.terms.changed.en-us', 3, 'sms', '', '{{if eq .category "offer_delisted"}}Node market offer {{.offer}} was delisted; your subscription runs until {{.at}}, then closes without renewal.{{else}}Node market offer {{.offer}} terms changed ({{.category}}); at renewal it will {{.action}} (renew/close).{{end}}', 'market.terms.changed.zh-cn'),
    ('node.availability.offline.en-us', 1, 'email', 'Node monitoring alert: node offline', 'Monitoring of node {{.node_name}} ({{.node_ip}}) failed and it was removed from DNS. Reason: {{.reason}}. Time: {{.occurred_at}}.', 'node.availability.offline.zh-cn'),
    ('node.availability.offline.en-us', 1, 'sms', '', 'Node {{.node_name}} ({{.node_ip}}) failed monitoring and is paused. Reason {{.reason}}, time {{.occurred_at}}.', 'node.availability.offline.zh-cn'),
    ('node.availability.recovered.en-us', 1, 'email', 'Node monitoring recovered: node back online', 'Monitoring of node {{.node_name}} ({{.node_ip}}) is normal again and it rejoined DNS. Reason: {{.reason}}. Time: {{.occurred_at}}.', 'node.availability.recovered.zh-cn'),
    ('node.availability.recovered.en-us', 1, 'sms', '', 'Node {{.node_name}} ({{.node_ip}}) is serving again. Reason {{.reason}}, time {{.occurred_at}}.', 'node.availability.recovered.zh-cn'),
    ('node.bandwidth.exceeded.en-us', 1, 'email', 'Node bandwidth exceeded: node disabled automatically', 'Bandwidth of node {{.node_name}} ({{.node_ip}}) exceeded its limit several times in a row, so it was disabled and removed from DNS at {{.occurred_at}} (UTC). Recent bandwidth: {{.bandwidth}}, limit: {{.bandwidth_limit}}. It recovers automatically once bandwidth drops below the limit and it has been disabled for 5 minutes.', 'node.bandwidth.exceeded.zh-cn'),
    ('node.bandwidth.exceeded.en-us', 1, 'sms', '', 'Node {{.node_name}} ({{.node_ip}}) bandwidth {{.bandwidth}} exceeded limit {{.bandwidth_limit}}; disabled at {{.occurred_at}}.', 'node.bandwidth.exceeded.zh-cn'),
    ('node.bandwidth.recovered.en-us', 1, 'email', 'Node bandwidth recovered: node serving again', 'Bandwidth of node {{.node_name}} ({{.node_ip}}) dropped below its limit; it recovered automatically and rejoined DNS at {{.occurred_at}} (UTC). Recent bandwidth: {{.bandwidth}}, limit: {{.bandwidth_limit}}.', 'node.bandwidth.recovered.zh-cn'),
    ('node.bandwidth.recovered.en-us', 1, 'sms', '', 'Node {{.node_name}} ({{.node_ip}}) bandwidth back to {{.bandwidth}} (limit {{.bandwidth_limit}}); serving again at {{.occurred_at}}.', 'node.bandwidth.recovered.zh-cn'),
    ('node.certificate.recovered.en-us', 1, 'email', 'Expired node certificate recovered: {{.node_name}}', 'The identity certificate of node {{.node_name}} ({{.node_ip}}) had been expired for {{.expired_for}} (expired {{.expired_at}} UTC). The node recovered automatically with its original key at {{.recovered_at}} (UTC); the new certificate expires {{.not_after}} (UTC). No action is needed. If this node should not come back, revoke its certificate in the node details.', 'node.certificate.recovered.zh-cn'),
    ('node.certificate.recovered.en-us', 1, 'sms', '', 'Node {{.node_name}} ({{.node_ip}}) certificate expired {{.expired_for}} ago and was renewed with its key; new expiry {{.not_after}}.', 'node.certificate.recovered.zh-cn'),
    ('node.dnspup.line_recovered.en-us', 1, 'email', 'dnspup line probe recovered: {{.node_name}} {{.line}}', 'The {{.line}} probe of node {{.node_name}} ({{.node_ip}}) recovered at {{.occurred_at}} (UTC).', 'node.dnspup.line_recovered.zh-cn'),
    ('node.dnspup.line_recovered.en-us', 1, 'sms', '', 'Node {{.node_name}} ({{.node_ip}}) {{.line}} probe recovered.', 'node.dnspup.line_recovered.zh-cn'),
    ('node.dnspup.line_unreachable.en-us', 1, 'email', 'dnspup line probe failing: {{.node_name}} {{.line}}', 'At {{.occurred_at}} (UTC), {{.failed}}/{{.total}} {{.line}} probe points kept failing for node {{.node_name}} ({{.node_ip}}). Main failure: {{.failure}}. This is a diagnostic alert and does not change node scheduling. Details: {{.link}}', 'node.dnspup.line_unreachable.zh-cn'),
    ('node.dnspup.line_unreachable.en-us', 1, 'sms', '', 'Node {{.node_name}} ({{.node_ip}}) {{.line}}: {{.failed}} probe points failing (main failure: {{.failure}}).', 'node.dnspup.line_unreachable.zh-cn'),
    ('node.dnspup.recovered.en-us', 1, 'email', 'dnspup probes recovered: {{.node_name}}', 'dnspup carrier probes of node {{.node_name}} ({{.node_ip}}) recovered at {{.occurred_at}} (UTC).', 'node.dnspup.recovered.zh-cn'),
    ('node.dnspup.recovered.en-us', 1, 'sms', '', 'Node {{.node_name}} ({{.node_ip}}) dnspup probes recovered.', 'node.dnspup.recovered.zh-cn'),
    ('node.dnspup.unreachable.en-us', 1, 'email', 'dnspup probes cannot reach node: {{.node_name}}', 'dnspup carrier probe points repeatedly found node {{.node_name}} ({{.node_ip}}) unreachable at {{.occurred_at}} (UTC) ({{.failed}}/{{.total}} points failed this round). The node is removed from DNS only if local probes fail too; a dnspup-only failure just alerts.', 'node.dnspup.unreachable.zh-cn'),
    ('node.dnspup.unreachable.en-us', 1, 'sms', '', 'Node {{.node_name}} ({{.node_ip}}) failing dnspup probes ({{.failed}}/{{.total}} points); still scheduled while local probes pass.', 'node.dnspup.unreachable.zh-cn'),
    ('node.install_trust.failed.en-us', 1, 'email', 'Node install trust document cannot update automatically', 'Since {{.since}} (UTC) the control plane has failed {{.failures}} times in a row to verify or republish the node install trust document (upgrade download URL {{.download}}); the latest failure was at {{.occurred_at}} (UTC), reason: {{.reason}}. The published document is unchanged, and node install commands copied from the console still point to the old download URL. Check that the control plane can resolve the admin domain, that it resolves to a public address, and the upgrade download URL and root CA file in /etc/cdnca-control/control.env. After fixing, it republishes within 10 minutes, or run control-api native-backup publish-node-install-trust on the control plane to publish now. Each failure streak is notified once.', 'node.install_trust.failed.zh-cn'),
    ('node.install_trust.failed.en-us', 1, 'sms', '', 'Node install trust document failed {{.failures}} times to update for {{.download}}; new nodes may not reach the upgrade URL.', 'node.install_trust.failed.zh-cn'),
    ('node.line_group.backup_ip_activated.en-us', 1, 'email', 'Line group switched to backup IPs: {{.line_group_name}}', 'The {{.address_family}} primary IPs of line group {{.line_group_name}} were removed by monitoring. DNS has pointed to the backup IPs {{.backup_addresses}} since {{.occurred_at}} (UTC). It switches back automatically when the primary IPs recover, with a separate notice.', 'node.line_group.backup_ip_activated.zh-cn'),
    ('node.line_group.backup_ip_activated.en-us', 1, 'sms', '', 'Line group {{.line_group_name}} {{.address_family}} primary IPs down; backup IPs {{.backup_addresses}} active since {{.occurred_at}}.', 'node.line_group.backup_ip_activated.zh-cn'),
    ('node.line_group.primary_ip_restored.en-us', 1, 'email', 'Line group primary IPs restored: {{.line_group_name}}', 'The {{.address_family}} primary IPs of line group {{.line_group_name}} recovered. DNS switched back to them at {{.occurred_at}} (UTC); backup IPs are no longer served.', 'node.line_group.primary_ip_restored.zh-cn'),
    ('node.line_group.primary_ip_restored.en-us', 1, 'sms', '', 'Line group {{.line_group_name}} {{.address_family}} primary IPs restored; backup IPs off since {{.occurred_at}}.', 'node.line_group.primary_ip_restored.zh-cn'),
    ('node.security.event.en-us', 1, 'email', 'Node security event: {{.node_name}} {{.event_kind}}', 'Node {{.node_name}} ({{.node_ip}}) had {{.event_kind}} at {{.occurred_at}} (UTC): client {{.client_ip}}, count {{.count}}, banned for {{.duration_seconds}} seconds. The same event on the same node is notified once per hour; see node security events for the full record.', 'node.security.event.zh-cn'),
    ('node.security.event.en-us', 1, 'sms', '', 'Node {{.node_name}} ({{.node_ip}}) {{.event_kind}}: client {{.client_ip}}, {{.count}} times, banned {{.duration_seconds}}s.', 'node.security.event.zh-cn'),
    ('node.security.list_truncated.en-us', 1, 'email', 'List over limit and truncated: {{.list_kind}} of node {{.node_name}}', 'The {{.list_kind}} of node {{.node_name}} ({{.node_ip}}) has {{.total}} entries, over the per-delivery limit of {{.limit}}. At {{.occurred_at}} (UTC), {{.truncated}} entries were dropped by priority and the rest was signed and delivered as usual; the remaining entries stay in effect. Ban lists keep all unban records and the bans with the longest remaining time; site drop lists keep the sites expiring last. Reduce bans on sites served by this node or spread the sites over more nodes. Each node and list is notified once per hour.', 'node.security.list_truncated.zh-cn'),
    ('node.security.list_truncated.en-us', 1, 'sms', '', 'Node {{.node_name}} {{.list_kind}} over limit; {{.truncated}} entries dropped before delivery.', 'node.security.list_truncated.zh-cn'),
    ('node.security.waf_ban.en-us', 1, 'email', 'WAF auto ban: {{.site_domain}} {{.client_ip}}', 'The WAF of site {{.site_domain}} automatically banned client {{.client_ip}} at {{.occurred_at}} (UTC) for {{.duration_seconds}} seconds. It was added to the ban list and delivered to all nodes serving the site. The same site and client are notified once per hour; see the ban list and security events for the full record.', 'node.security.waf_ban.zh-cn'),
    ('node.security.waf_ban.en-us', 1, 'sms', '', 'WAF of site {{.site_domain}} banned client {{.client_ip}} for {{.duration_seconds}}s.', 'node.security.waf_ban.zh-cn'),
    ('node.security.xdp.en-us', 1, 'email', 'Node security event: {{.node_name}} {{.event_kind}}', 'Node {{.node_name}} ({{.node_ip}}) at {{.occurred_at}} (UTC): {{.event_kind}} ({{.xdp_reason_text}}, {{.xdp_event}}/{{.xdp_reason}}). During the fallback, nftables enforces all kernel rules and the XDP_FILTER capability is withdrawn; it recovers automatically after XDP is reattached. The same event on the same node is notified once per hour.', 'node.security.xdp.zh-cn'),
    ('node.security.xdp.en-us', 1, 'sms', '', 'Node {{.node_name}} ({{.node_ip}}): {{.event_kind}} ({{.xdp_reason_text}}).', 'node.security.xdp.zh-cn'),
    ('package.auto_renew.failed.en-us', 1, 'email', 'Package auto-renewal failed', 'Auto-renewal of package {{.subscription_id}} failed: {{.reason}}. The package expires on {{.ends_at}}. Please top up or renew manually.', 'package.auto_renew.failed.zh-cn'),
    ('package.auto_renew.failed.en-us', 1, 'sms', '', 'Package {{.subscription_id}} auto-renewal failed ({{.reason}}); expires {{.ends_at}}. Please act in time.', 'package.auto_renew.failed.zh-cn'),
    ('package.auto_renew.succeeded.en-us', 1, 'email', 'Package auto-renewed', 'Package {{.subscription_id}} was renewed automatically. {{.amount}} CNY was charged from your balance; it is now valid until {{.ends_at}}.', 'package.auto_renew.succeeded.zh-cn'),
    ('package.auto_renew.succeeded.en-us', 1, 'sms', '', 'Package {{.subscription_id}} auto-renewed for {{.amount}} CNY; valid until {{.ends_at}}.', 'package.auto_renew.succeeded.zh-cn'),
    ('package.monitor.bandwidth.recovered.en-us', 1, 'email', 'Package bandwidth recovered', 'Bandwidth of package {{.subscription_id}} in period {{.period_key}} is back to {{.metric_value}}; recovery threshold {{.threshold_value}}.', 'package.monitor.bandwidth.recovered.zh-cn'),
    ('package.monitor.bandwidth.recovered.en-us', 1, 'sms', '', 'Package {{.subscription_id}} bandwidth back to {{.metric_value}}, recovery threshold {{.threshold_value}}, period {{.period_key}}.', 'package.monitor.bandwidth.recovered.zh-cn'),
    ('package.monitor.bandwidth.triggered.en-us', 1, 'email', 'Package bandwidth threshold reached', 'Bandwidth of package {{.subscription_id}} in period {{.period_key}} reached {{.metric_value}}; alert threshold {{.threshold_value}}.', 'package.monitor.bandwidth.triggered.zh-cn'),
    ('package.monitor.bandwidth.triggered.en-us', 1, 'sms', '', 'Package {{.subscription_id}} bandwidth reached {{.metric_value}}, threshold {{.threshold_value}}, period {{.period_key}}.', 'package.monitor.bandwidth.triggered.zh-cn'),
    ('package.monitor.cc_rule_auto_switch.en-us', 1, 'email', 'CC protection switched automatically: {{.domain}}', 'Site {{.domain}} triggered CC auto switch at {{.engaged_at}}: {{.trigger_qps}} requests per second (threshold {{.qps_total}}), {{.trigger_5xx}} 5xx per second (threshold {{.qps_5xx}}). The auto switch rules are now active; default protection resumes after traffic stays below the thresholds for {{.recover_minutes}} minutes.', 'package.monitor.cc_rule_auto_switch.zh-cn'),
    ('package.monitor.cc_rule_auto_switch.en-us', 1, 'sms', '', 'Site {{.domain}} had abnormal traffic at {{.engaged_at}} ({{.trigger_qps}} req/s); CC rules switched, auto restore after about {{.recover_minutes}} min.', 'package.monitor.cc_rule_auto_switch.zh-cn'),
    ('package.monitor.connections.recovered.en-us', 1, 'email', 'Package connections recovered', 'Connections of package {{.subscription_id}} in period {{.period_key}} are back to {{.metric_value}}; recovery threshold {{.threshold_value}}.', 'package.monitor.connections.recovered.zh-cn'),
    ('package.monitor.connections.recovered.en-us', 1, 'sms', '', 'Package {{.subscription_id}} connections back to {{.metric_value}}, recovery threshold {{.threshold_value}}, period {{.period_key}}.', 'package.monitor.connections.recovered.zh-cn'),
    ('package.monitor.connections.triggered.en-us', 1, 'email', 'Package connections threshold reached', 'Connections of package {{.subscription_id}} in period {{.period_key}} reached {{.metric_value}}; alert threshold {{.threshold_value}}.', 'package.monitor.connections.triggered.zh-cn'),
    ('package.monitor.connections.triggered.en-us', 1, 'sms', '', 'Package {{.subscription_id}} connections reached {{.metric_value}}, threshold {{.threshold_value}}, period {{.period_key}}.', 'package.monitor.connections.triggered.zh-cn'),
    ('package.monitor.expiration.recovered.en-us', 1, 'email', 'Package expiry reminder cleared', 'The expiry of package {{.subscription_id}} was updated to {{.ends_at}}; the reminder for threshold {{.threshold_value}} is cleared. Period: {{.period_key}}.', 'package.monitor.expiration.recovered.zh-cn'),
    ('package.monitor.expiration.recovered.en-us', 1, 'sms', '', 'Package {{.subscription_id}} now expires {{.ends_at}}; reminder for threshold {{.threshold_value}} cleared, period {{.period_key}}.', 'package.monitor.expiration.recovered.zh-cn'),
    ('package.monitor.expiration.triggered.en-us', 1, 'email', 'Package expiry reminder', 'Package {{.subscription_id}} expires on {{.ends_at}}. Reminder threshold: {{.threshold_value}}. Period: {{.period_key}}.', 'package.monitor.expiration.triggered.zh-cn'),
    ('package.monitor.expiration.triggered.en-us', 1, 'sms', '', 'Package {{.subscription_id}} expires {{.ends_at}}, reminder threshold {{.threshold_value}}, period {{.period_key}}.', 'package.monitor.expiration.triggered.zh-cn'),
    ('package.monitor.traffic.recovered.en-us', 1, 'email', 'Package traffic recovered', 'Traffic of package {{.subscription_id}} in period {{.period_key}} is back to {{.metric_value}}; recovery threshold {{.threshold_value}}.', 'package.monitor.traffic.recovered.zh-cn'),
    ('package.monitor.traffic.recovered.en-us', 1, 'sms', '', 'Package {{.subscription_id}} traffic back to {{.metric_value}}, recovery threshold {{.threshold_value}}, period {{.period_key}}.', 'package.monitor.traffic.recovered.zh-cn'),
    ('package.monitor.traffic.triggered.en-us', 1, 'email', 'Package traffic threshold reached', 'Traffic of package {{.subscription_id}} in period {{.period_key}} reached {{.metric_value}}; alert threshold {{.threshold_value}}.', 'package.monitor.traffic.triggered.zh-cn'),
    ('package.monitor.traffic.triggered.en-us', 1, 'sms', '', 'Package {{.subscription_id}} traffic reached {{.metric_value}}, threshold {{.threshold_value}}, period {{.period_key}}.', 'package.monitor.traffic.triggered.zh-cn'),
    ('package.traffic.recovered.en-us', 1, 'email', 'Package traffic available again', 'Traffic of package {{.subscription_id}} in period {{.period_key}} is available again. Current usage {{.metric_value}}, limit {{.threshold_value}}. Related sites were restored automatically.', 'package.traffic.recovered.zh-cn'),
    ('package.traffic.recovered.en-us', 1, 'sms', '', 'Package {{.subscription_id}} traffic available again: usage {{.metric_value}}, limit {{.threshold_value}} (period {{.period_key}}).', 'package.traffic.recovered.zh-cn'),
    ('package.traffic.suspended.en-us', 1, 'email', 'Package traffic over limit', 'Package {{.subscription_id}} used {{.metric_value}} of traffic in period {{.period_key}}, over the limit {{.threshold_value}}. Depending on platform settings, related sites may have been disabled; they are restored automatically after you renew, upgrade or buy a traffic pack.', 'package.traffic.suspended.zh-cn'),
    ('package.traffic.suspended.en-us', 1, 'sms', '', 'Package {{.subscription_id}} traffic {{.metric_value}} exceeded limit {{.threshold_value}} (period {{.period_key}}).', 'package.traffic.suspended.zh-cn'),
    ('payment.market_topup.rejected.en-us', 1, 'email', 'Direct top-up receipt rejected by the market: {{.topup}}', 'Node market direct top-up {{.topup}} was received by the payment channel of this control plane, but the market rejected the receipt report (reason: {{.reason_code}}), so the subscriber''s balance with you did not increase. Check the transaction in the payment channel backend and contact the subscriber.', 'payment.market_topup.rejected.zh-cn'),
    ('payment.market_topup.rejected.en-us', 1, 'sms', '', 'Alert: receipt of node market direct top-up {{.topup}} was rejected ({{.reason_code}}); subscriber balance not increased.', 'payment.market_topup.rejected.zh-cn'),
    ('payment.plugin.alert.en-us', 1, 'email', 'Payment plugin alert: {{.plugin_id}}', 'Payment plugin {{.plugin_id}} reported order {{.order_id}} as paid, but the control plane could not verify it (reason: {{.reason_code}}), so it was not credited. If this happens often, check the plugin version or disable the plugin.', 'payment.plugin.alert.zh-cn'),
    ('payment.plugin.alert.en-us', 1, 'sms', '', 'Alert: payment of order {{.order_id}} reported by plugin {{.plugin_id}} failed verification ({{.reason_code}}); not credited.', 'payment.plugin.alert.zh-cn'),
    ('payment.reconcile.mismatch.en-us', 1, 'email', 'Payment reconciliation mismatch: {{.channel_name}} {{.day}}', 'Reconciliation of payment channel {{.channel_name}} for {{.day}} (UTC) does not match the payment plugin statement: {{.remote_only}} paid remotely but not credited locally (received ones are credited automatically), {{.local_only}} credited locally with no remote record, {{.mismatch}} with a different amount or transaction number. Check the details under Payment channels > Reconciliation.', 'payment.reconcile.mismatch.zh-cn'),
    ('payment.reconcile.mismatch.en-us', 1, 'sms', '', 'Payment channel {{.channel_name}} {{.day}} reconciliation: {{.remote_only}} missing, {{.local_only}} not found remotely, {{.mismatch}} mismatched. Please check.', 'payment.reconcile.mismatch.zh-cn'),
    ('probe.dnspup.balance_exhausted.en-us', 1, 'email', 'dnspup quota used up, node probes stopped', 'The dnspup quota for this month is used up. Node availability probes stopped and node-local probes decide instead (nodes are not marked offline for missing probe data); alerts continue. Top up points at dnspup; settings: {{.link}}', 'probe.dnspup.balance_exhausted.zh-cn'),
    ('probe.dnspup.balance_exhausted.en-us', 1, 'sms', '', 'dnspup monthly quota used up; node probes fell back to local checks. Top up at dnspup: {{.link}}', 'probe.dnspup.balance_exhausted.zh-cn'),
    ('probe.dnspup.balance_low.en-us', 1, 'email', 'dnspup quota low, node probes slowed down', '{{.remaining}} dnspup probes are left this month, below the alert line {{.threshold}}. Node availability probes were slowed down automatically. Top up points at dnspup; settings: {{.link}}', 'probe.dnspup.balance_low.zh-cn'),
    ('probe.dnspup.balance_low.en-us', 1, 'sms', '', 'dnspup has {{.remaining}} probes left this month, below {{.threshold}}; node probes slowed. Top up: {{.link}}', 'probe.dnspup.balance_low.zh-cn'),
    ('probe.dnspup.degraded.en-us', 1, 'email', 'dnspup probes paused', 'The dnspup probe source is paused: {{.reason_text}} (dnspup error code {{.code}}). Until {{.until}}, origin and aggregated edge probes run directly from nodes and the control plane. Open {{.link}} to check the dnspup key, quota and source settings.', 'probe.dnspup.degraded.zh-cn'),
    ('probe.dnspup.degraded.en-us', 1, 'sms', '', 'dnspup probes paused: {{.reason_text}} ({{.code}}); other sources used until {{.until}}. Handle it at: {{.link}}', 'probe.dnspup.degraded.zh-cn'),
    ('reseller.prepaid.low_balance.en-us', 1, 'email', 'Reseller prepaid balance low', 'Your reseller prepaid balance is only {{.remaining}} CNY, below the alert line of {{.threshold}} CNY. For each order of your packages, the platform deducts the wholesale price from this balance; orders are rejected when it cannot cover the wholesale price. Top up under Finance in the console.', 'reseller.prepaid.low_balance.zh-cn'),
    ('reseller.prepaid.low_balance.en-us', 1, 'sms', '', 'Reseller prepaid balance is {{.remaining}} CNY, below {{.threshold}} CNY; customers cannot buy your packages once it is short. Please top up.', 'reseller.prepaid.low_balance.zh-cn'),
    ('security_activation.recovery_failed.en-us', 1, 'email', 'Security policy canary rollback failed: {{.site_domain}}', 'After the security policy canary of site {{.site_domain}} (candidate {{.candidate_id}}) ended, rolling nodes back to the original config failed {{.attempts}} times in a row, and automatic retries stopped at {{.occurred_at}} (UTC). Some nodes may still run the candidate config. Check why the rollback deployment failed under Deployments, fix it and republish the site.', 'security_activation.recovery_failed.zh-cn'),
    ('security_activation.recovery_failed.en-us', 1, 'sms', '', 'Site {{.site_domain}} security canary rollback failed {{.attempts}} times; auto rollback stopped. Please act soon.', 'security_activation.recovery_failed.zh-cn'),
    ('security.attack.detected.en-us', 1, 'email', 'Attack alert: {{.domain}}', 'From {{.window_start}} to {{.window_end}} ({{.window_minutes}} minutes), WAF / CC protection handled {{.events}} requests on site {{.domain}}: {{.blocked}} blocked, {{.challenged}} challenged, {{.banned}} temporarily banned, from {{.clients}} source IPs; top source {{.top_client_ip}}, main detector {{.top_detector}}. See Block logs in the console for details. The same site is not alerted again within {{.cooldown_minutes}} minutes.', 'security.attack.detected.zh-cn'),
    ('security.attack.detected.en-us', 1, 'sms', '', 'Site {{.domain}} blocked {{.events}} attack requests in {{.window_minutes}} min from {{.clients}} IPs. See Block logs in the console.', 'security.attack.detected.zh-cn'),
    ('security.escalate.blackhole_drop_confirmed.en-us', 1, 'email', 'Attack escalation: nodes of {{.domain}} confirmed dropping', 'After site {{.domain}} entered the blackhole ({{.occurred_at}}), its {{.nodes}} node(s) confirmed the drop rules at {{.confirmed_at}}; residual traffic still reaching the nodes is dropped. {{.limited}}Once the attack stays below the thresholds and the hold time ends, it steps back automatically.', 'security.escalate.blackhole_drop_confirmed.zh-cn'),
    ('security.escalate.blackhole_drop_confirmed.en-us', 1, 'sms', '', 'Site {{.domain}} blackhole active: {{.nodes}} node(s) confirmed dropping its residual traffic.', 'security.escalate.blackhole_drop_confirmed.zh-cn'),
    ('security.escalate.blackhole.en-us', 2, 'email', 'Attack escalation: {{.domain}} entered the blackhole', 'At {{.occurred_at}}, site {{.domain}} was escalated to level D "blackhole" because of a sustained volumetric attack ({{.qps}} requests/s and {{.bps}} bit/s across all nodes): DNS now points to 0.0.0.0 (TTL 60 seconds) and access is temporarily interrupted. Nodes are applying the drop rules for this site; you will be notified again when all nodes confirm. Once the attack stays below the thresholds and the hold time ends, it steps back automatically; see status and history under Attack escalation in the console.', 'security.escalate.blackhole.zh-cn'),
    ('security.escalate.blackhole.en-us', 1, 'sms', '', 'Site {{.domain}} is under a volumetric attack and entered the blackhole: DNS points to 0.0.0.0, access is down; auto restore after the attack.', 'security.escalate.blackhole.zh-cn'),
    ('security.escalate.cname_change_required.en-us', 1, 'email', 'Attack escalation: please update the CNAME of {{.domain}}', 'So that site {{.domain}} can switch lines on its own under attack, the platform split out a dedicated CNAME for it: {{.cname}}. The platform did not change your DNS automatically because: {{.reason}}. At your DNS provider, change the record of this domain to a CNAME pointing to {{.cname}}, then click "I have changed it" under Attack escalation in the console. Until then, attack escalation cannot switch lines for this site.', 'security.escalate.cname_change_required.zh-cn'),
    ('security.escalate.cname_change_required.en-us', 1, 'sms', '', 'Site {{.domain}} has a dedicated CNAME; point its DNS to CNAME {{.cname}} so escalation can switch lines. Reason: {{.reason}}', 'security.escalate.cname_change_required.zh-cn'),
    ('security.escalate.unlimited.en-us', 1, 'email', 'Attack escalation: {{.domain}} moved to the unlimited protection line group', 'Site {{.domain}} is under a volumetric attack beyond what the high-defense line group can absorb. At {{.occurred_at}} the platform moved it to the unlimited protection line group {{.line_group}} (not blackholed), and visitors can access it as usual. It steps back automatically after the attack subsides; no action is needed.', 'security.escalate.unlimited.zh-cn'),
    ('security.escalate.unlimited.en-us', 1, 'sms', '', 'Site {{.domain}} under volumetric attack moved to line group {{.line_group}} at {{.occurred_at}}; still online, auto switch back later.', 'security.escalate.unlimited.zh-cn'),
    ('security.waf.auto_exclusion_active.en-us', 1, 'email', 'WAF auto exclusion active: {{.domain}}', 'Parameter {{.param}} of site {{.domain}} is no longer checked by WAF rule {{.rule}} (shadow period passed, valid until {{.until}}). High-score rules, detectors and shape checks still apply. You can revoke it under WAF / Smart auto in the console.', 'security.waf.auto_exclusion_active.zh-cn'),
    ('security.waf.auto_exclusion_expired.en-us', 1, 'email', 'WAF auto exclusion expired: {{.domain}}', 'The auto exclusion of parameter {{.param}} of site {{.domain}} from WAF rule {{.rule}} expired (not enough evidence in the last 7 days to extend it). The rule checks it again.', 'security.waf.auto_exclusion_expired.zh-cn'),
    ('security.waf.auto_exclusion_revoked.en-us', 1, 'email', 'WAF auto exclusion revoked: {{.domain}}', 'Parameter {{.param}} of site {{.domain}} is checked by WAF rule {{.rule}} again (reason: {{.reason}}).', 'security.waf.auto_exclusion_revoked.zh-cn'),
    ('site.origin.failover.hold.en-us', 1, 'email', 'All origins down, origin level kept: {{.domain}}', 'At {{.occurred_at}}, all origins of site {{.domain}} were unavailable; the current origin level {{.active_level}} is kept. Failback mode: {{.failback_mode}}. Check origin status under Site settings - Origin in the console{{.action}}.', 'site.origin.failover.hold.zh-cn'),
    ('site.origin.failover.hold.en-us', 1, 'sms', '', 'Site {{.domain}}: all origins down; origin level {{.active_level}} kept.', 'site.origin.failover.hold.zh-cn'),
    ('site.origin.failover.en-us', 1, 'email', 'Origin failover: {{.domain}}', 'At {{.switched_at}}, origin of site {{.domain}} switched from {{.from_level}} to {{.to_level}}. Reason: {{.reason}}. Failback mode: {{.failback_mode}}. Check origin status under Site settings - Origin in the console{{.action}}.', 'site.origin.failover.zh-cn'),
    ('site.origin.failover.en-us', 1, 'sms', '', 'Site {{.domain}} origin switched from {{.from_level}} to {{.to_level}}: {{.reason}}.', 'site.origin.failover.zh-cn'),
    ('site.origin.recovered.en-us', 1, 'email', 'Origin recovered, switch back manually: {{.domain}}', 'The {{.level}} of site {{.domain}} passed probes again at {{.recovered_at}}; the site still uses {{.active_level}} (manual failback). Click "Switch back to primary" under Site settings - Origin in the console.', 'site.origin.recovered.zh-cn'),
    ('site.origin.recovered.en-us', 1, 'sms', '', 'Site {{.domain}} {{.level}} recovered; switch back manually in the console.', 'site.origin.recovered.zh-cn'),
    ('ticket_created.en-us', 1, 'email', 'Ticket submitted', 'Your ticket #{{.ticket_no}} "{{.subject}}" was submitted. We will handle it as soon as possible.', 'ticket_created'),
    ('ticket_created.en-us', 1, 'sms', '', 'Your ticket #{{.ticket_no}} was submitted. We will handle it soon.', 'ticket_created'),
    ('ticket_replied.en-us', 1, 'email', 'New reply on your ticket', 'Your ticket #{{.ticket_no}} "{{.subject}}" has a new reply from support. Sign in to the console to view it.', 'ticket_replied'),
    ('ticket_replied.en-us', 1, 'sms', '', 'Your ticket #{{.ticket_no}} has a new reply. Sign in to the console to view it.', 'ticket_replied'),
    ('ticket_staff_created.en-us', 1, 'email', 'New ticket #{{.ticket_no}}', 'User {{.username}} submitted ticket #{{.ticket_no}} "{{.subject}}". Sign in to the console to handle it.', 'ticket_staff_created'),
    ('ticket_staff_created.en-us', 1, 'sms', '', 'New ticket #{{.ticket_no}} is waiting. Sign in to the console to view it.', 'ticket_staff_created'),
    ('ticket_staff_overdue.en-us', 1, 'email', 'Ticket #{{.ticket_no}} overdue', 'Ticket #{{.ticket_no}} "{{.subject}}" from user {{.username}} has had no support reply for over 24 hours. Sign in to the console and handle it soon.', 'ticket_staff_overdue'),
    ('ticket_staff_overdue.en-us', 1, 'sms', '', 'Ticket #{{.ticket_no}} has had no reply for over 24 hours. Please handle it soon.', 'ticket_staff_overdue'),
    ('ticket_staff_replied.en-us', 1, 'email', 'User replied to ticket #{{.ticket_no}}', 'User {{.username}} replied to ticket #{{.ticket_no}} "{{.subject}}". Sign in to the console to handle it.', 'ticket_staff_replied'),
    ('ticket_staff_replied.en-us', 1, 'sms', '', 'Ticket #{{.ticket_no}} has a user reply. Sign in to the console to view it.', 'ticket_staff_replied'),
    ('ticket_status_changed.en-us', 1, 'email', 'Ticket status updated', 'The status of your ticket #{{.ticket_no}} "{{.subject}}" changed to: {{.status_label}}.', 'ticket_status_changed'),
    ('ticket_status_changed.en-us', 1, 'sms', '', 'Your ticket #{{.ticket_no}} status changed to: {{.status_label}}.', 'ticket_status_changed')
