LOCK TABLE schema_migrations IN ACCESS EXCLUSIVE MODE;

-- 通知模板补英文，按收件人语言发送。
-- 1. users.locale 记控制台界面语言（PUT /v1/account/locale 写入；NULL = 未设置，按平台默认中文）。
-- 2. 每个迁移种子模板的当前版本补一份英文：template_id 把 .zh-cn 换成 .en-us（无后缀的追加 .en-us），
--    版本、渠道、变量与中文同一行一致（变量从中文行复制）。tenant_member_invitation 本身是中英双语，不补。
--    发送时英文收件人取同版本的 .en-us，缺失或变量不一致即回落中文。
--    运营已在模板页自建的同号 .en-us 版本保留不覆盖。
DO $migration_704$
BEGIN
    IF (SELECT count(*) FROM schema_migrations) <> 703 OR
       (SELECT max(version) FROM schema_migrations) <> 703 OR NOT EXISTS (
        SELECT 1 FROM schema_migrations WHERE version=703 AND
        migration_id='703_site_origin_pool_site_revision' AND
        integrity_state='verified' AND metadata_recorded_at IS NOT NULL AND applied_at IS NOT NULL
       ) OR EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema=current_schema() AND table_name='users' AND column_name='locale'
       ) THEN
        RAISE EXCEPTION 'migration 704 requires the exact verified 703 release head' USING ERRCODE='P7040';
    END IF;
END;
$migration_704$;

ALTER TABLE users ADD COLUMN locale text CHECK (locale IN ('zh-CN', 'zh-TW', 'en-US'));

CREATE TEMP TABLE notification_templates_en_704 (
    template_id text NOT NULL, version bigint NOT NULL, channel text NOT NULL,
    subject text NOT NULL, body text NOT NULL, source_id text NOT NULL
);

;

DO $migration_704_check$
BEGIN
    IF (SELECT count(*) FROM notification_templates_en_704 translation
        JOIN notification_templates source
          ON source.template_id = translation.source_id AND source.version = translation.version
         AND source.channel = translation.channel) <> 224 THEN
        RAISE EXCEPTION 'migration 704 English templates do not match their Chinese sources' USING ERRCODE='P7040';
    END IF;
END;
$migration_704_check$;

-- 回退只删本迁移插入的行：运营在升级前后自建的同号 .en-us 模板不在这里，回退时保留。
CREATE TABLE notification_templates_seed_704 (
    template_id text NOT NULL,
    version bigint NOT NULL,
    channel text NOT NULL,
    PRIMARY KEY (template_id, version, channel)
);

WITH inserted AS (
    SELECT translation.template_id, source.version, source.channel, translation.subject, translation.body,
        source.variables, clock_timestamp()
    FROM notification_templates_en_704 translation
    JOIN notification_templates source
      ON source.template_id = translation.source_id AND source.version = translation.version
     AND source.channel = translation.channel
    ON CONFLICT (template_id, version, channel) DO NOTHING
    RETURNING template_id, version, channel
)
SELECT template_id, version, channel FROM inserted;

DROP TABLE notification_templates_en_704;
